-- --- ganesha_standard / Naivedyam & Tambulam -----------------------------------------
update public.pooja_steps set
  step_title_en = 'Naivedyam & Tambulam',
  step_title_ta = 'நைவேத்யம் & தாம்பூலம்',
  instruction_en = 'Place the naivedyam in front of the deity. Say the vyahritis and the Gayatri, then sprinkle water around the plate in a circle. Offer a spoon of water as the bed beneath the food, then feed the five breaths one at a time, moving the right hand towards the deity at each. Only then name what is being offered. Water again as the cover over it, then the hands and the mouth rinsed, then the betel leaf and areca nut. Nothing is tasted before this step. In an evening pooja the sprinkling line is said the other way round: ritaṃ tvā satyena pariṣiñcāmi.',
  instruction_ta = 'நைவேத்தியத்தை சுவாமியின் முன் வைக்கவும். வ்யாஹ்ருதிகளையும் காயத்ரியையும் சொல்லி, தட்டைச் சுற்றி ஜலம் தெளிக்கவும். உணவின் அடியில் விரிப்பாக ஒரு உத்தரிணி ஜலம் விடவும்; பின் ஐந்து ப்ராணன்களுக்கும் ஒவ்வொன்றாக, ஒவ்வொரு முறையும் வலது கையை சுவாமியை நோக்கி நகர்த்தி, சமர்ப்பிக்கவும். அதன் பிறகுதான் என்ன படைக்கப்படுகிறது என்று சொல்ல வேண்டும். மீண்டும் ஜலம் மூடியாக, பின் கை கழுவுதல், வாய் கொப்பளித்தல், பிறகு தாம்பூலம். இதற்கு முன் எதையும் ருசி பார்க்கக் கூடாது. மாலைப் பூஜையில் தெளிக்கும் வரி மாறி வரும்: ருதம் த்வா ஸத்யேந பரிஷிஞ்சாமி.',
  mantra_sanskrit = 'ॐ भूर्भुवस्सुवः । तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि ।
धियो यो नः प्रचोदयात् ॥
देव सवितः प्रसुव ।
सत्यं त्वा ऋतेन परिषिञ्चामि ।
अमृतमस्तु । अमृतोपस्तरणमसि ।
ॐ प्राणाय स्वाहा । ॐ अपानाय स्वाहा ।
ॐ व्यानाय स्वाहा । ॐ उदानाय स्वाहा ।
ॐ समानाय स्वाहा ।
सुगंधान् सुकृतांश्चैव मोदकान् घृत पाचितान् ।
नैवेद्यं गृह्यतां देव चणमुद्गैः प्रकल्पितान् ॥
भक्ष्यं भोज्यं च लेह्यं च चोष्यं पानीयमेव च ।
इदं गृहाण नैवेद्यं मया दत्तं विनायक ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः नैवेद्यं समर्पयामि ।
मध्ये मध्ये पानीयं समर्पयामि ।
अमृतापिधानमसि । उत्तरापोशनं समर्पयामि ।
हस्तौ प्रक्षालयामि । पादौ प्रक्षालयामि ।
शुद्धाचमनीयं समर्पयामि ।
पूगीफलसमायुक्तं नागवल्लीदळैर्युतम् ।
कर्पूरचूर्णसंयुक्तं तांबूलं प्रतिगृह्यताम् ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः तांबूलं समर्पयामि ।
तांबूल चर्वणानंतरं आचमनीयं समर्पयामि ।',
  mantra_tamil = 'ஓம் பூர்புவஸ்ஸுவ꞉ । தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி ।
தியோ யோ ந꞉ ப்ரசோதயாத் ॥
தேவ ஸவித꞉ ப்ரஸுவ ।
ஸத்யம் த்வா ருதேந பரிஷிஞ்சாமி ।
அம்ருதமஸ்து । அம்ருதோபஸ்தரணமஸி ।
ஓம் ப்ராணாய ஸ்வாஹா । ஓம் அபாநாய ஸ்வாஹா ।
ஓம் வ்யாநாய ஸ்வாஹா । ஓம் உதாநாய ஸ்வாஹா ।
ஓம் ஸமாநாய ஸ்வாஹா ।
ஸுகம்தாந் ஸுக்ருதாம்ஶ்சைவ மோதகாந் க்ருத பாசிதாந் ।
நைவேத்யம் க்ருஹ்யதாம் தேவ சணமுத்கை꞉ ப்ரகல்பிதாந் ॥
பக்ஷ்யம் போஜ்யம் ச லேஹ்யம் ச சோஷ்யம் பாநீயமேவ ச ।
இதம் க்ருஹாண நைவேத்யம் மயா தத்தம் விநாயக ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ நைவேத்யம் ஸமர்பயாமி ।
மத்யே மத்யே பாநீயம் ஸமர்பயாமி ।
அம்ருதாபிதாநமஸி । உத்தராபோஶநம் ஸமர்பயாமி ।
ஹஸ்தௌ ப்ரக்ஷாலயாமி । பாதௌ ப்ரக்ஷாலயாமி ।
ஶுத்தாசமநீயம் ஸமர்பயாமி ।
பூகீபலஸமாயுக்தம் நாகவல்லீதளைர்யுதம் ।
கர்பூரசூர்ணஸம்யுக்தம் தாம்பூலம் ப்ரதிக்ருஹ்யதாம் ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ தாம்பூலம் ஸமர்பயாமி ।
தாம்பூல சர்வணாநம்தரம் ஆசமநீயம் ஸமர்பயாமி ।',
  mantra_translit = 'oṃ bhūrbhuvassuvaḥ । tatsaviturvareṇyaṃ bhargo devasya dhīmahi ।
dhiyo yo naḥ pracodayāt ॥
deva savitaḥ prasuva ।
satyaṃ tvā ṛtena pariṣiñcāmi ।
amṛtamastu । amṛtopastaraṇamasi ।
oṃ prāṇāya svāhā । oṃ apānāya svāhā ।
oṃ vyānāya svāhā । oṃ udānāya svāhā ।
oṃ samānāya svāhā ।
sugaṃdhān sukṛtāṃścaiva modakān ghṛta pācitān ।
naivedyaṃ gṛhyatāṃ deva caṇamudgaiḥ prakalpitān ॥
bhakṣyaṃ bhojyaṃ ca lehyaṃ ca coṣyaṃ pānīyameva ca ।
idaṃ gṛhāṇa naivedyaṃ mayā dattaṃ vināyaka ॥
oṃ śrī siddhivināyaka svāmine namaḥ naivedyaṃ samarpayāmi ।
madhye madhye pānīyaṃ samarpayāmi ।
amṛtāpidhānamasi । uttarāpośanaṃ samarpayāmi ।
hastau prakṣālayāmi । pādau prakṣālayāmi ।
śuddhācamanīyaṃ samarpayāmi ।
pūgīphalasamāyuktaṃ nāgavallīdal̤airyutam ।
karpūracūrṇasaṃyuktaṃ tāṃbūlaṃ pratigṛhyatām ॥
oṃ śrī siddhivināyaka svāmine namaḥ tāṃbūlaṃ samarpayāmi ।
tāṃbūla carvaṇānaṃtaraṃ ācamanīyaṃ samarpayāmi ।',
  source_ref = 'Deity verses from the vrata kalpam (Telugu, round-trip verified). The naivedyam frame -- vyahritis, Gayatri, satyam tva rtena parishinchami, amritopastaranam, the five pranas, amritapidhanam and the rinsings -- from StotraNidhi Sri Maha Ganapathi Shodashopachara Puja (IAST, round-trip verified), which is generic to any Smartha naivedyam and so is used in both poojas. ORDER FOLLOWS PRACTICE, NOT THE PAGE: StotraNidhi prints the verse and its samarpayami before the frame; here the frame comes first and the offering is named after the five breaths, as reported by this project’s owner. "deva savitah prasuva" is in NEITHER published page; it is Apastamba prayoga and the owner’s practice, included on that basis and flagged for practitioner review. Svara marks are stripped: the vyahritis, the Gayatri and the prana mantras carry accents in print and this app does not render them yet.',
  verified_by = null,
  verified_at = null,
  updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en in ('Naivedyam', 'Naivedyam & Tambulam');

-- --- ganesha_standard / Karpura Neerajanam --------------------------------
update public.pooja_steps set
  instruction_en = 'Stand. Light the camphor and circle it clockwise before the deity, at the feet, then the middle, then the face, ringing the bell with the left hand. Offer a spoon of water after. This is the point the rest of the house is called in.',
  instruction_ta = 'எழுந்து நிற்கவும். கற்பூரத்தை ஏற்றி, இடது கையால் மணி அடித்தபடி, சுவாமியின் முன் வலமாகச் சுழற்றவும் — பாதம், பின் இடை, பின் திருமுகம். பிறகு ஒரு உத்தரிணி ஜலம் விடவும். வீட்டில் உள்ள மற்றவர்களை அழைக்க வேண்டிய இடம் இதுவே.',
  mantra_sanskrit = 'घृतवर्ति सहस्रैश्च कर्पूरशकलैस्तथा ।
नीराजनं मया दत्तं गृहाण वरदो भव ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः नीराजनं समर्पयामि ।
नीराजनानंतरं आचमनीयं समर्पयामि ।',
  mantra_tamil = 'க்ருதவர்தி ஸஹஸ்ரைஶ்ச கர்பூரஶகலைஸ்ததா ।
நீராஜநம் மயா தத்தம் க்ருஹாண வரதோ பவ ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ நீராஜநம் ஸமர்பயாமி ।
நீராஜநாநம்தரம் ஆசமநீயம் ஸமர்பயாமி ।',
  mantra_translit = 'ghṛtavarti sahasraiśca karpūraśakalaistathā ।
nīrājanaṃ mayā dattaṃ gṛhāṇa varado bhava ॥
oṃ śrī siddhivināyaka svāmine namaḥ nīrājanaṃ samarpayāmi ।
nīrājanānaṃtaraṃ ācamanīyaṃ samarpayāmi ।',
  source_ref = 'StotraNidhi Sri Siddhi Vinayaka Vrata Kalpam (Telugu), round-trip verified Telugu->Devanagari by scripts/build-upachara-mantras.mjs. Replaces the one-line placeholder this step carried from the original app, which cited no text at all.',
  verified_by = null,
