  updated_at = now()
where pooja_id = 'ganesha_standard' and step_title_en = 'Karpura Neerajanam';

-- --- ganesha_standard / Mantra Pushpam & Namaskaram -----------------------
update public.pooja_steps set
  instruction_en = 'Hold flowers in both cupped palms, recite, and offer them at the feet. Then turn clockwise in place three times for the pradakshina, prostrate full length, and finish with the prarthana.',
  instruction_ta = 'இரு கைகளிலும் புஷ்பங்களை ஏந்தி, ஸ்லோகம் சொல்லி, திருவடிகளில் சமர்ப்பிக்கவும். பின் நின்ற இடத்திலேயே வலமாக மூன்று முறை சுற்றி பிரதக்ஷிணம் செய்து, சாஷ்டாங்கமாக நமஸ்கரித்து, பிரார்த்தனையுடன் முடிக்கவும்.',
  mantra_sanskrit = 'गणाधिप नमस्तेऽस्तु उमापुत्राघनाशन ।
विनायकेशतनय सर्वसिद्धिप्रदायक ॥
एकदंतैकवदन तथा मूषकवाहन ।
कुमारगुरवे तुभ्यमर्पयामि सुमांजलिम् ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः मंत्रपुष्पं समर्पयामि ।
प्रदक्षिणं करिष्यामि सततं मोदकप्रिय ।
मद्विघ्नं हरये शीघ्रं भक्तानामिष्टदायक ॥
आखुवाहन देवेश विश्वव्यापिन् विनायक ।
प्रदक्षिणं करोमि त्वां प्रसीद वरदो भव ॥
यानिकानि च पापानि जन्मांतरकृतानि च ।
तानि तानि प्रणश्यंति प्रदक्षिण पदे पदे ॥
पापोऽहं पापकर्माऽहं पापात्मा पापसंभवः ।
त्राहि मां कृपया देव शरणागतवत्सल ॥
अन्यथा शरणं नास्ति त्वमेव शरणं मम ।
तस्मात्कारुण्य भावेन रक्ष रक्ष विनायक ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः आत्मप्रदक्षिण नमस्कारान् समर्पयामि ।
नमो नमो गणेशाय नमस्ते विश्वरूपिणे ।
निर्विघ्नं कुरु मे कामं नमामि त्वां गजानना ॥
अगजानन पद्मार्कं गजानन महर्निशम् ।
अनेकदं तं भक्तानां एकदंतमुपास्महे ॥
नमस्ते भिन्नदंताय नमस्ते हरसूनवे ।
ममाभीष्टप्रदो भूयो विनायक नमोऽस्तु ते ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः साष्टांग नमस्कारं समर्पयामि ।
प्रसीद देवदेवेश प्रसीद गणनायक ।
ईप्सितं मे वरं देहि परत्र च परांगतिम् ॥
विनायक वरं देहि महात्मन् मोदकप्रिय ।
अविघ्नं कुरु मे देव सर्वकार्येषु सर्वदा ॥
ॐ श्री सिद्धिविनायक स्वामिने नमः प्रार्थन नमस्कारान् समर्पयामि ।',
  mantra_tamil = 'கணாதிப நமஸ்தேஸ்து உமாபுத்ராகநாஶந ।
விநாயகேஶதநய ஸர்வஸித்திப்ரதாயக ॥
ஏகதம்தைகவதந ததா மூஷகவாஹந ।
குமாரகுரவே துப்யமர்பயாமி ஸுமாம்ஜலிம் ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ மம்த்ரபுஷ்பம் ஸமர்பயாமி ।
ப்ரதக்ஷிணம் கரிஷ்யாமி ஸததம் மோதகப்ரிய ।
மத்விக்நம் ஹரயே ஶீக்ரம் பக்தாநாமிஷ்டதாயக ॥
ஆகுவாஹந தேவேஶ விஶ்வவ்யாபிந் விநாயக ।
ப்ரதக்ஷிணம் கரோமி த்வாம் ப்ரஸீத வரதோ பவ ॥
யாநிகாநி ச பாபாநி ஜந்மாம்தரக்ருதாநி ச ।
தாநி தாநி ப்ரணஶ்யம்தி ப்ரதக்ஷிண பதே பதே ॥
பாபோஹம் பாபகர்மாஹம் பாபாத்மா பாபஸம்பவ꞉ ।
த்ராஹி மாம் க்ருபயா தேவ ஶரணாகதவத்ஸல ॥
அந்யதா ஶரணம் நாஸ்தி த்வமேவ ஶரணம் மம ।
தஸ்மாத்காருண்ய பாவேந ரக்ஷ ரக்ஷ விநாயக ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ ஆத்மப்ரதக்ஷிண நமஸ்காராந் ஸமர்பயாமி ।
நமோ நமோ கணேஶாய நமஸ்தே விஶ்வரூபிணே ।
நிர்விக்நம் குரு மே காமம் நமாமி த்வாம் கஜாநநா ॥
அகஜாநந பத்மார்கம் கஜாநந மஹர்நிஶம் ।
அநேகதம் தம் பக்தாநாம் ஏகதம்தமுபாஸ்மஹே ॥
நமஸ்தே பிந்நதம்தாய நமஸ்தே ஹரஸூநவே ।
மமாபீஷ்டப்ரதோ பூயோ விநாயக நமோஸ்து தே ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ ஸாஷ்டாம்க நமஸ்காரம் ஸமர்பயாமி ।
ப்ரஸீத தேவதேவேஶ ப்ரஸீத கணநாயக ।
ஈப்ஸிதம் மே வரம் தேஹி பரத்ர ச பராம்கதிம் ॥
விநாயக வரம் தேஹி மஹாத்மந் மோதகப்ரிய ।
அவிக்நம் குரு மே தேவ ஸர்வகார்யேஷு ஸர்வதா ॥
ஓம் ஶ்ரீ ஸித்திவிநாயக ஸ்வாமிநே நம꞉ ப்ரார்தந நமஸ்காராந் ஸமர்பயாமி ।',
  mantra_translit = 'gaṇādhipa namaste''stu umāputrāghanāśana ।
vināyakeśatanaya sarvasiddhipradāyaka ॥
ekadaṃtaikavadana tathā mūṣakavāhana ।
kumāragurave tubhyamarpayāmi sumāṃjalim ॥
oṃ śrī siddhivināyaka svāmine namaḥ maṃtrapuṣpaṃ samarpayāmi ।
pradakṣiṇaṃ kariṣyāmi satataṃ modakapriya ।
