-- --- varalakshmi_vratham / Naivedyam, Paniyam & Tambulam ---------------------
update public.pooja_steps set
  instruction_en = 'Place the food in front. Say the vyahritis and the Gayatri, then sprinkle water around the plate in a circle. Offer a spoon of water as the bed beneath it, then feed the five breaths one at a time. Only then name what is offered, then the water to drink and the betel leaf. Water again as the cover, then the hands and the mouth rinsed. Cover the food while reciting, and do not taste anything before this step. In an evening pooja the sprinkling line is said the other way round: ritaṃ tvā satyena pariṣiñcāmi.',
  instruction_ta = 'உணவை முன்னால் வைக்கவும். வ்யாஹ்ருதிகளையும் காயத்ரியையும் சொல்லி, தட்டைச் சுற்றி ஜலம் தெளிக்கவும். அடியில் விரிப்பாக ஒரு உத்தரிணி ஜலம் விட்டு, ஐந்து ப்ராணன்களுக்கும் ஒவ்வொன்றாகச் சமர்ப்பிக்கவும். அதன் பிறகுதான் படைப்பதைச் சொல்ல வேண்டும்; பின் பானீயமும் தாம்பூலமும். மீண்டும் ஜலம் மூடியாக, பின் கை கழுவுதல், வாய் கொப்பளித்தல். ஸ்லோகம் சொல்லும்போது உணவை மூடி வைக்கவும்; இதற்கு முன் எதையும் ருசி பார்க்கக் கூடாது. மாலைப் பூஜையில் தெளிக்கும் வரி மாறி வரும்: ருதம் த்வா ஸத்யேந பரிஷிஞ்சாமி.',
  mantra_sanskrit = case when mantra_sanskrit like '%भूर्भुवस्सुवः%' then mantra_sanskrit
    else 'ॐ भूर्भुवस्सुवः । तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि ।
धियो यो नः प्रचोदयात् ॥
देव सवितः प्रसुव ।
सत्यं त्वा ऋतेन परिषिञ्चामि ।
अमृतमस्तु । अमृतोपस्तरणमसि ।
ॐ प्राणाय स्वाहा । ॐ अपानाय स्वाहा ।
ॐ व्यानाय स्वाहा । ॐ उदानाय स्वाहा ।
ॐ समानाय स्वाहा ।
' || mantra_sanskrit || '
मध्ये मध्ये पानीयं समर्पयामि ।
अमृतापिधानमसि । उत्तरापोशनं समर्पयामि ।
हस्तौ प्रक्षालयामि । पादौ प्रक्षालयामि ।
शुद्धाचमनीयं समर्पयामि ।' end,
  mantra_tamil = case when mantra_tamil like '%பூர்புவஸ்ஸுவ%' then mantra_tamil
    else 'ஓம் பூர்புவஸ்ஸுவ꞉ । தத்ஸவிதுர்வரேண்யம் பர்கோ தேவஸ்ய தீமஹி ।
தியோ யோ ந꞉ ப்ரசோதயாத் ॥
தேவ ஸவித꞉ ப்ரஸுவ ।
ஸத்யம் த்வா ருதேந பரிஷிஞ்சாமி ।
அம்ருதமஸ்து । அம்ருதோபஸ்தரணமஸி ।
ஓம் ப்ராணாய ஸ்வாஹா । ஓம் அபாநாய ஸ்வாஹா ।
ஓம் வ்யாநாய ஸ்வாஹா । ஓம் உதாநாய ஸ்வாஹா ।
ஓம் ஸமாநாய ஸ்வாஹா ।
' || mantra_tamil || '
மத்யே மத்யே பாநீயம் ஸமர்பயாமி ।
அம்ருதாபிதாநமஸி । உத்தராபோஶநம் ஸமர்பயாமி ।
ஹஸ்தௌ ப்ரக்ஷாலயாமி । பாதௌ ப்ரக்ஷாலயாமி ।
ஶுத்தாசமநீயம் ஸமர்பயாமி ।' end,
  mantra_translit = case when mantra_translit like '%bhūrbhuvassuvaḥ%' then mantra_translit
    else 'oṃ bhūrbhuvassuvaḥ । tatsaviturvareṇyaṃ bhargo devasya dhīmahi ।
dhiyo yo naḥ pracodayāt ॥
deva savitaḥ prasuva ।
satyaṃ tvā ṛtena pariṣiñcāmi ।
amṛtamastu । amṛtopastaraṇamasi ।
oṃ prāṇāya svāhā । oṃ apānāya svāhā ।
oṃ vyānāya svāhā । oṃ udānāya svāhā ।
oṃ samānāya svāhā ।
' || mantra_translit || '
madhye madhye pānīyaṃ samarpayāmi ।
amṛtāpidhānamasi । uttarāpośanaṃ samarpayāmi ।
hastau prakṣālayāmi । pādau prakṣālayāmi ।
śuddhācamanīyaṃ samarpayāmi ।' end,
  source_ref = 'Deity verses from the vrata kalpam (Telugu, round-trip verified). The naivedyam frame -- vyahritis, Gayatri, satyam tva rtena parishinchami, amritopastaranam, the five pranas, amritapidhanam and the rinsings -- from StotraNidhi Sri Maha Ganapathi Shodashopachara Puja (IAST, round-trip verified), which is generic to any Smartha naivedyam and so is used in both poojas. ORDER FOLLOWS PRACTICE, NOT THE PAGE: StotraNidhi prints the verse and its samarpayami before the frame; here the frame comes first and the offering is named after the five breaths, as reported by this project’s owner. "deva savitah prasuva" is in NEITHER published page; it is Apastamba prayoga and the owner’s practice, included on that basis and flagged for practitioner review. Svara marks are stripped: the vyahritis, the Gayatri and the prana mantras carry accents in print and this app does not render them yet.',
  verified_by = null,
  verified_at = null,
  updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Naivedyam, Paniyam & Tambulam';

-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  -- Nothing here may still be a one-liner. Counting LINES, not characters:
  -- the first draft asserted 200 characters and the neerajanam is a legitimate
  -- 154, so the gate failed on correct content. What actually distinguishes
  -- these from what they replaced is that each is a sequence.
  select count(*) into n from public.pooja_steps
   where ((pooja_id = 'ganesha_standard' and step_title_en = 'Dhoopam & Deepam') or (pooja_id = 'ganesha_standard' and step_title_en in ('Naivedyam', 'Naivedyam & Tambulam')) or (pooja_id = 'ganesha_standard' and step_title_en = 'Karpura Neerajanam') or (pooja_id = 'ganesha_standard' and step_title_en = 'Mantra Pushpam & Namaskaram') or (pooja_id = 'varalakshmi_vratham' and step_title_en = 'Naivedyam, Paniyam & Tambulam'))
     and (mantra_sanskrit is null
          or (length(mantra_sanskrit) - length(replace(mantra_sanskrit, chr(10), ''))) < 3);
  if n > 0 then raise exception '% offering steps are still a single line', n; end if;
  -- Both naivedyams must carry the whole frame, in the practised order.
  select count(*) into n from public.pooja_steps
   where step_title_en in ('Naivedyam & Tambulam', 'Naivedyam, Paniyam & Tambulam')
     and (mantra_sanskrit not like '%भूर्भुवस्सुवः%'
          or mantra_sanskrit not like '%अमृतोपस्तरणमसि%'
          or mantra_sanskrit not like '%समानाय स्वाहा%'
          or mantra_sanskrit not like '%अमृतापिधानमसि%'
          or mantra_sanskrit not like '%उत्तरापोशनं%'
          or position('समानाय स्वाहा' in mantra_sanskrit) > position('अमृतापिधानमसि' in mantra_sanskrit));
  if n > 0 then raise exception '% naivedyam steps are missing part of the frame', n; end if;
  select count(*) into n from public.pooja_steps
   where step_title_en in ('Naivedyam & Tambulam', 'Naivedyam, Paniyam & Tambulam');
  if n <> 2 then raise exception 'expected 2 naivedyam steps, found %', n; end if;
  -- No placeholder source_ref may survive on a step this migration touched.
  select count(*) into n from public.pooja_steps
   where ((pooja_id = 'ganesha_standard' and step_title_en = 'Dhoopam & Deepam') or (pooja_id = 'ganesha_standard' and step_title_en in ('Naivedyam', 'Naivedyam & Tambulam')) or (pooja_id = 'ganesha_standard' and step_title_en = 'Karpura Neerajanam') or (pooja_id = 'ganesha_standard' and step_title_en = 'Mantra Pushpam & Namaskaram') or (pooja_id = 'varalakshmi_vratham' and step_title_en = 'Naivedyam, Paniyam & Tambulam'))
     and source_ref like '%pending vaidika review%';
  if n > 0 then raise exception '% touched steps still carry the draft source_ref', n; end if;
end $$;

commit;

